<script setup lang="ts">const props=defineProps<{locale:'zh'|'en'}>();const input=ref('0');const converted=computed(()=>{const text=input.value.trim();if(!/^-?\d+$/.test(text))return null;const value=Number(text);const ms=text.replace('-','').length<=10?value*1000:value;const date=new Date(ms);return Number.isNaN(date.getTime())?null:{iso:date.toISOString(),local:date.toLocaleString(props.locale==='zh'?'zh-CN':'en-US',{dateStyle:'full',timeStyle:'long'})}});const {copied,copy}=useCopy()</script><template><div class="tool-form"><label>{{locale==='zh'?'Unix 时间戳（秒或毫秒）':'Unix timestamp (seconds or milliseconds)'}}<input v-model="input" inputmode="numeric" placeholder="0"></label><div class="result-header"><span>{{locale==='zh'?'转换结果':'CONVERTED TIME'}}</span><button type="button" :disabled="!converted" @click="converted&&copy(converted.iso)">{{copied?(locale==='zh'?'已复制':'Copied'):(locale==='zh'?'复制 ISO':'Copy ISO')}}</button></div><div v-if="converted" class="time-result"><span>{{locale==='zh'?'本地时间':'Local time'}}</span><strong>{{converted.local}}</strong><span>UTC / ISO 8601</span><code>{{converted.iso}}</code></div><p v-else class="form-note">{{locale==='zh'?'请输入有效的时间戳。':'Enter a valid timestamp.'}}</p></div></template>